                          make_shape(Int<BM>{}, Int<BK>{}),
                          make_stride(Int<BK>{}, Int<1>{}));      // (m,k)
  Tensor sB = make_tensor(make_smem_ptr(sB_raw),
                          make_shape(Int<BK>{}, Int<BN>{}),
                          make_stride(Int<BN>{}, Int<1>{}));      // (k,n)

