  const int tx = tid & 31;
  const int ty = tid >> 5;
  const int m0 = ty * 4;
  const int n0 = tx * 4;

  const int m_lim = min(BM, M - m_start);
  const int n_lim = min(BN, N - n_start);

  float acc[4][4];
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    #pragma unroll
    for (int j = 0; j < 4; ++j) {
      acc[i][j] = 0.0f;
    }
